'use strict';
const recurringMetrics=['n','mean','median','sd','min','max','cp','cpk','pp','ppk','oosCount','oosRate'];
const recurringComparisonMetrics=['n','mean','sd','cp','cpk','pp','ppk','oosRate'];
const recurringReason=r=>wt('recurring.'+r.code,(r.params||[]).map(v=>typeof v==='number'?v.toLocaleString(I18n.numberLocale,{maximumFractionDigits:6}):v));
const recurringClock=g=>g.timeKind==='instant'?'UTC':g.timeKind==='wall'?wt('batch.wallClock'):wt('none');
const recurringLabel=g=>[g.product,g.item,g.equipment,g.unit,`LSL ${g.specInvalid?'?':fmt(g.lsl)} / USL ${g.specInvalid?'?':fmt(g.usl)}`,recurringClock(g)].filter(Boolean).join(' / ')||wt('value');
function recurringDate(r){if(!Number.isFinite(r.date))return '';const iso=new Date(r.date).toISOString();return r.timeKind==='instant'?iso:iso.replace(/Z$/,'');}
function recurringIssues(w){const all=[...(w.result.normalized?.issues||[]),...(w.result.issues||[])],seen=new Set();return all.filter(i=>{const key=JSON.stringify(i);if(seen.has(key))return false;seen.add(key);return true;});}
function recurringStatus(g){return `<strong class="${g.attention?'warning-text':''}">${esc(wt(g.status))}</strong>${g.reasons.length?`<details><summary>${esc(wt('issue'))} (${g.reasons.length})</summary><ul>${g.reasons.map(r=>`<li>${esc(recurringReason(r))}</li>`).join('')}</ul></details>`:''}`;}
function recurringComparisonBar(c,label){
 if(!c||c.current.mean===null||c.previous.mean===null)return '—';
 const a=c.current.mean,b=c.previous.mean,min=Math.min(0,a,b),max=Math.max(0,a,b),span=max-min||1;
 if(!Number.isFinite(span))return '—';
 const x=n=>8+(n-min)/span*164,zero=x(0),bar=(v,y,color)=>`<rect x="${Math.min(zero,x(v))}" y="${y}" width="${Math.max(1,Math.abs(x(v)-zero))}" height="8" fill="${color}"/>`;
 const title=`${label}: ${wt('previous')} ${fmt(b)} / ${wt('current')} ${fmt(a)} / ${wt('change')} ${fmt(c.deltas.mean.absolute)}`;
 return chartBase(180,34,`<title>${esc(title)}</title><line x1="${zero}" x2="${zero}" y1="1" y2="32" stroke="#9aa9b7"/>${bar(b,4,'#9aa9b7')}${bar(a,20,'#288f7c')}`,title)+`<small>${esc(wt('change'))}: ${fmt(c.deltas.mean.absolute)}</small>`;
}
function recurringChart(g,range=false){
 const r=g.result;if(!r)return reportText(wt('unavailable'));
 const groups=new Map(r.groups.map(x=>[x.index,x]));
 const records=(range?r.rangeRecords:r.chartRecords).map(p=>{const group=groups.get(p.index),start=r.chart==='xbar'?group.start:p.index,end=r.chart==='xbar'?group.end:p.index,a=g.selectedRecords[start],b=g.selectedRecords[end];return {...p,position:end+1,lot:b?.lot||'',time:b?.date,startPosition:start+1,startLot:a?.lot||'',startTime:a?.date,isSubgroup:r.chart==='xbar'};});
 const label=recurringLabel(g)+' · '+(range?r.chart==='imr'?'MR':'R':r.chart==='imr'?'Individuals':'Xbar');
 return spcChart(records,range?r.rangeMean:r.mean,range?r.rangeLcl:r.lcl,range?r.rangeUcl:r.ucl,label,{axis:{mode:'index'},width:700,height:250,lsl:!range&&r.chart==='imr'?r.lsl:null,usl:!range&&r.chart==='imr'?r.usl:null,alarms:range?r.rangeSignals:r.alarms,utc:g.timeKind==='instant'})+reportText(viewText('count',[Math.min(records.length,500),records.length,records.length>500?viewText('capped'):'']));
}
function recurringStatsTable(groups){return [[...['product','item','equipment','unit','lsl','usl',...recurringMetrics,'batch.timeBasis','status'].map(wt)],...groups.map(g=>[g.product,g.item,g.equipment,g.unit,g.lsl,g.usl,...recurringMetrics.map(k=>g.stats[k]),recurringClock(g),[wt(g.status),...g.reasons.map(recurringReason)].join('\n')])];}
function recurringComparisonTable(result){
 const groups=new Map(result.groups.map(g=>[g.key,g]));
 return [[wt('product'),wt('item'),wt('equipment'),wt('unit'),wt('lsl'),wt('usl'),wt('name'),wt('current'),wt('previous'),wt('change'),wt('relative')],...result.comparisons.flatMap(c=>{const g=groups.get(c.key);return recurringComparisonMetrics.map(k=>[g.product,g.item,g.equipment,g.unit,g.lsl,g.usl,wt(k),c.current[k],c.previous[k],c.deltas[k].absolute,c.deltas[k].relative]);})];
}
function recurringAuditTable(result){return [[wt('source'),wt('sheet'),wt('row'),wt('date'),wt('product'),wt('lot'),wt('equipment'),wt('item'),wt('value'),wt('unit'),wt('lsl'),wt('usl'),wt('current'),wt('previous')],...result.audit.map(a=>{const r=a.record;return [r.file,r.sheet,r.row,recurringDate(r)||r.rawDate,r.product,r.lot,r.equipment,r.item,r.rawValue,r.unit,r.rawLsl,r.rawUsl,wt('recurring.'+a.currentStatus),wt('recurring.'+a.previousStatus)];})];}
function recurringCompactStats(groups){return [[wt('product')+' / '+wt('item'),wt('n'),wt('mean'),'Cpk',wt('oosRate'),wt('status')],...groups.map(g=>[recurringLabel(g),g.stats.n,g.stats.mean,g.stats.cpk,g.stats.oosRate,wt(g.status)])];}
function recurringGroupKpis(g){
 const table=keys=>reportTable(keys.map(k=>wt(k)),[keys.map(k=>k==='lsl'||k==='usl'?g[k]:g.stats[k])]);
 return `<div style="break-inside:avoid">${reportSection(recurringLabel(g),table(['n','mean','sd','cp','cpk','pp','ppk'])+table(['median','min','max','lsl','usl','oosCount','oosRate'])+reportText([wt(g.status),...g.reasons.map(recurringReason)].join('\n')))}</div>`;
}
function renderRecurringResults(w){
 const r=w.result,all=r.groups||[],groups=w.settings.attentionOnly?all.filter(g=>g.attention):all,shown=groups.slice(0,300),issues=recurringIssues(w);
 const headers=[wt('product')+' / '+wt('item'),wt('n'),wt('mean'),wt('cpk'),wt('oosRate'),wt('status')];
 const rows=shown.map(g=>`<tr data-quality-row="${all.indexOf(g)}"><td><strong>${esc([g.product,g.item].filter(Boolean).join(' / '))}</strong><br><small>${esc([g.equipment,g.unit,`LSL ${g.specInvalid?'?':fmt(g.lsl)} / USL ${g.specInvalid?'?':fmt(g.usl)}`,recurringClock(g)].filter(Boolean).join(' · '))}</small><br><button class="wf-table-action" data-quality-detail="${all.indexOf(g)}" ${g.result?'':'disabled'} aria-label="${esc(wt('details')+' · '+recurringLabel(g))}">${esc(wt('details'))}</button></td><td>${g.stats.n}</td><td>${fmt(g.stats.mean)}${g.comparison?`<div style="max-width:160px">${recurringComparisonBar(g.comparison,recurringLabel(g))}</div>`:''}</td><td>${fmt(g.stats.cpk)}</td><td>${fmt(g.stats.oosRate,2)}</td><td>${recurringStatus(g)}</td></tr>`).join('');
 const summary=[[wt('n'),r.counts.currentValid],[wt('excluded'),r.counts.currentExcluded],[wt('attention'),all.filter(g=>g.attention).length]],stats=recurringStatsTable(groups),comparisons=recurringComparisonTable(r),audit=recurringAuditTable(r);
 return `<section class="panel"><div class="panel-head"><h2>${esc(wt('dashboard'))}</h2><label class="check"><input type="checkbox" id="rq-attention-only" ${w.settings.attentionOnly?'checked':''}>${esc(wt('attentionOnly'))}</label></div><div class="stats">${summary.map(([label,value])=>`<div class="stat"><div class="stat-label">${esc(label)}</div><div class="stat-value">${value.toLocaleString(I18n.numberLocale)}</div></div>`).join('')}</div>${groups.length?`<div class="table-wrap"><table class="recurring-dashboard"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`:`<p class="empty">${esc(wt('noData'))}</p>`}${groups.length>300?reportText(wt('reportLimit',[300,groups.length])):''}<details><summary>${esc(wt('normalizedData'))} · ${esc(wt('dashboard'))}</summary>${tableSection(wt('dashboard'),stats,300)}</details></section><section class="panel"><details><summary>${esc(wt('comparison'))}</summary>${reportText(wt('noCausality'))}${tableSection(wt('comparison'),comparisons,300)}</details></section><section class="panel"><details><summary>${esc(wt('audit'))} (${issues.length})</summary>${reportTable([wt('source'),wt('row'),wt('issue')],issues.slice(0,300).map(i=>[i.file||'',i.row??'',recurringReason(i)]))}${issues.length>300?reportText(wt('reportLimit',[300,issues.length])):''}${tableSection(wt('normalizedData'),audit,300)}</details><details><summary>${esc(wt('method'))}</summary>${reportText(wt('qualityMethod'))}${reportText(wt('periodHelp'))}</details></section>`;
}
function recurringOpenDetail(index){
 const w=wfState('recurring'),g=w.result?.groups[index];if(!g?.result)return;
 const headers=[wt('date'),wt('lot'),wt('product'),wt('equipment'),g.item||wt('value'),wt('source'),wt('row')];
 // Use ISO text to preserve wall-clock versus zoned times across mixed workbook epochs.
 const d={headers,rows:g.selectedRecords.map(r=>[recurringDate(r)||r.rawDate,r.lot,r.product,r.equipment,r.rawValue,[r.file,r.sheet].filter(Boolean).join(' / '),r.row]),name:recurringLabel(g),date1904:false,isDemo:w.sources.every(s=>s.isDemo),sourceHeaderRow:1,sourceHasHeader:true,
  workflowContext:{source:'recurring',minSamples:w.settings.minSamples,rationalSubgroups:w.settings.rationalSubgroups,unit:g.unit,lsl:g.lsl,usl:g.usl,specInvalid:g.specInvalid},provenance:g.selectedRecords.map(r=>({sourceId:r.sourceId,file:r.file,sheet:r.sheet,row:r.row}))};
 state.data=d;state.col=4;state.lsl=g.specInvalid||g.lsl===null?'':String(g.lsl);state.usl=g.specInvalid||g.usl===null?'':String(g.usl);state.unit=g.unit;
 state.quality={date:0,lot:g.order==='lot'?1:-1,product:2,productValue:'',order:g.order,chart:w.settings.chart,subgroupSize:w.settings.subgroupSize,rules:[...w.settings.rules]};
 resetQualityRange();state.imports.capability={workbook:null,raw:null,headerRow:1,hasHeader:true,headerDetection:null,sheet:'',appliedPreset:'',restoreNote:''};navigate('capability');
}
function bindWorkflowResults(){
 if(state.view!=='recurring')return;
 if($('#rq-attention-only'))$('#rq-attention-only').onchange=e=>{wfState('recurring').settings.attentionOnly=e.target.checked;renderWorkflow();};
 $$('[data-quality-detail]').forEach(b=>b.onclick=()=>safe(()=>recurringOpenDetail(Number(b.dataset.qualityDetail))));
 $$('[data-quality-row]').forEach(row=>row.onclick=e=>{if(e.target.closest('button,details,summary,a,input'))return;safe(()=>recurringOpenDetail(Number(row.dataset.qualityRow)));});
}
function buildRecurringReport(){
 const w=wfState('recurring'),r=w.result,s=w.settings;if(!r||!r.valid)throw Error(wt('noData'));
 const title=s.reportTitle||wt('recurring.title'),conditions=[[wt('name'),wt('value')],[wt('reportTitle'),title],[wt('from'),s.from||wt('all')],[wt('to'),s.to||wt('all')],[wt('previousFrom'),s.previousFrom||'—'],[wt('previousTo'),s.previousTo||'—'],...['product','item','equipment','lot'].map(k=>[wt(k),s[k]||wt('all')]),[wt('chart'),s.chart==='imr'?'Individuals / Moving Range':'Xbar-R'],[wt('subgroupSize'),s.chart==='imr'?1:s.subgroupSize],[wt('rationalSubgroups'),s.rationalSubgroups?wt('recurring.confirmed'):wt('recurring.notConfirmed')],[wt('minSamples'),s.minSamples],[wt('rules'),s.rules.map(n=>`${n}. ${SPCCore.rules[n]}`).join('\n')],[wt('cpkThreshold'),s.cpkThreshold],[wt('deltaThreshold'),s.deltaThreshold],[wt('attentionOos'),String(s.attentionOos)],[wt('attentionSpc'),String(s.attentionSpc)],[wt('n'),r.counts.currentValid],[wt('excluded'),r.counts.currentExcluded],[wt('reportCharts'),s.reportCharts],[wt('method'),wt('qualityMethod')],[wt('date'),wt('periodHelp')]];
 const sources=[[wt('source'),wt('sheet'),wt('header'),wt('hasHeader'),wt('row'),wt('review')],...w.sources.map(x=>[x.name,x.sheet,x.table.sourceHeaderRow||1,x.table.sourceHasHeader!==false?wt('recurring.confirmed'):wt('recurring.notConfirmed'),x.table.rows.length,JSON.stringify(x.mapping)])];
 const stats=recurringStatsTable(r.groups),attention=recurringStatsTable(r.groups.filter(g=>g.attention)),previous=recurringStatsTable(r.previousGroups),comparison=recurringComparisonTable(r),audit=recurringAuditTable(r),issues=recurringIssues(w);
 const issueRows=[[wt('source'),wt('sheet'),wt('row'),wt('issue')],...issues.map(i=>[i.file||'',i.sheet||'',i.row??'',recurringReason(i)]),...r.groups.flatMap(g=>g.reasons.map(i=>[recurringLabel(g),'','',recurringReason(i)]))];
 const normalized=[[wt('source'),wt('sheet'),wt('row'),wt('date'),wt('product'),wt('lot'),wt('equipment'),wt('item'),wt('value'),wt('unit'),wt('lsl'),wt('usl'),wt('issue')],...(r.normalized?.records||r.audit.map(a=>a.record)).map(x=>[x.file,x.sheet,x.row,recurringDate(x)||x.rawDate,x.product,x.lot,x.equipment,x.item,x.value,x.unit,x.rawLsl,x.rawUsl,(x.issues||[]).map(recurringReason).join('\n')])];
 const chartGroups=r.groups.filter(g=>g.result).slice(0,Math.min(12,Math.max(0,s.reportCharts??4))),charts=chartGroups.map(g=>`<div style="break-inside:avoid">${reportSection(recurringLabel(g),recurringChart(g)+recurringChart(g,true)+reportText(g.reasons.map(recurringReason).join('\n')))}</div>`).join('');
 const chartRows=[[wt('product'),wt('item'),wt('equipment'),wt('unit'),wt('chart'),wt('row'),wt('lot'),wt('value'),'LCL','CL','UCL'],...r.groups.flatMap(g=>{if(!g.result)return [];const byIndex=new Map(g.result.groups.map(x=>[x.index,x]));return [false,true].flatMap(range=>(range?g.result.rangeRecords:g.result.chartRecords).map(p=>{const end=g.result.chart==='xbar'?byIndex.get(p.index).end:p.index;return [g.product,g.item,g.equipment,g.unit,range?g.result.chart==='imr'?'MR':'R':g.result.chart==='imr'?'Individuals':'Xbar',end+1,g.selectedRecords[end]?.lot||'',p.value,range?g.result.rangeLcl:g.result.lcl,range?g.result.rangeMean:g.result.mean,range?g.result.rangeUcl:g.result.ucl];}));})];
 const sourceSummary=sources.map(row=>row.slice(0,5));
 const groupMap=new Map(r.groups.map(g=>[g.key,g]));
 const comparisonHtml=r.comparisons.slice(0,300).map(c=>`<div style="break-inside:avoid">${reportSection(recurringLabel(groupMap.get(c.key)),reportTable([wt('name'),wt('current'),wt('previous'),wt('change'),wt('relative')],recurringComparisonMetrics.map(k=>[wt(k),c.current[k],c.previous[k],c.deltas[k].absolute,c.deltas[k].relative])))}</div>`).join('');
 const oosRecords=new Set(r.groups.flatMap(g=>g.result?g.result.oos.map(p=>g.selectedRecords[p.index]):[]));
 const exceptions=r.audit.filter(a=>!['included','filtered','outsidePeriod'].includes(a.currentStatus)||a.record.issues?.length||oosRecords.has(a.record)),exceptionRows=[[wt('source'),wt('row'),wt('item'),wt('value'),wt('issue')],...exceptions.map(a=>[a.record.file+' / '+a.record.sheet,a.record.row,a.record.item,a.record.rawValue,[wt('current')+': '+wt('recurring.'+a.currentStatus),...(a.record.issues||[]).map(recurringReason),...(oosRecords.has(a.record)?[I18n.t('reports.bfab264df4')]:[])].join('\n')])];
 conditions.push([wt('normalizedData')+' / N',r.audit.length],[wt('recurring.outsidePeriod')+' / N',r.audit.filter(a=>a.currentStatus==='outsidePeriod').length],[wt('recurring.filtered')+' / N',r.audit.filter(a=>a.currentStatus==='filtered').length]);
 const groupKpis=r.groups.slice(0,300).map(recurringGroupKpis).join('');
 let html=`<h1>${esc(title)}</h1><p class="report-meta">Manufacturing Toolbox · ${esc(new Date().toISOString())}</p>`+tableSection(wt('conditions'),conditions)+tableSection(wt('source'),sourceSummary)+tableSection(wt('dashboard'),recurringCompactStats(r.groups),300)+tableSection(wt('attention'),recurringCompactStats(r.groups.filter(g=>g.attention)),300)+groupKpis+(r.groups.length>300?reportText(wt('reportLimit',[300,r.groups.length])):'')+reportSection(wt('chart'),charts+reportText(wt('recurring.chartLimit',[chartGroups.length,r.groups.filter(g=>g.result).length])))+reportSection(wt('comparison'),comparisonHtml+reportText(wt('noCausality')))+(r.comparisons.length>300?reportText(wt('reportLimit',[300,r.comparisons.length])):'')+tableSection(wt('issue'),issueRows,300)+tableSection(wt('audit'),exceptionRows,300)+reportText(wt('reportNote'));
 const sheets=[[wt('conditions'),conditions],[wt('source'),sources],[wt('dashboard'),stats],[wt('attention'),attention],[wt('previous'),previous],[wt('comparison'),comparison],[wt('audit'),audit],[wt('issue'),issueRows],[wt('normalizedData'),normalized],[wt('chart'),chartRows],...w.sources.map((x,i)=>[wt('source')+' '+(i+1),[x.table.headers,...x.table.rows]])].map(([name,data],i)=>[String(name).replace(/[\\/?*\[\]:]/g,' ').slice(0,26)+' '+(i+1),data]);
 return {title,filename:title+'.xlsx',sheets,html};
}
